def knapsack(items, capacity):
    # Positive integer weights; nonnegative integer values.
    if capacity < 0 or any(w <= 0 or v < 0 for w,v in items):
        raise ValueError("Invalid knapsack input")
    n = len(items)
    dp = [[0]*(capacity+1) for _ in range(n+1)]
    for i, (weight,value) in enumerate(items, 1):
        for c in range(capacity+1):
            dp[i][c] = dp[i-1][c]
            if weight <= c:
                dp[i][c] = max(dp[i][c], value+dp[i-1][c-weight])
    chosen, c = [], capacity
    for i in range(n,0,-1):
        if dp[i][c] != dp[i-1][c]:
            chosen.append(i-1)
            c -= items[i-1][0]
    return dp[n][capacity], list(reversed(chosen))

def knapsack_value(items, capacity):
    dp = [0]*(capacity+1)
    for weight,value in items:
        for c in range(capacity,weight-1,-1):
            dp[c] = max(dp[c],value+dp[c-weight])
    return dp[capacity]

