function knapsack(items, capacity) {
  if(!Number.isInteger(capacity)||capacity<0||items.some(([w,v])=>!Number.isInteger(w)||w<=0||!Number.isFinite(v)||v<0))throw Error('Invalid input');
  const n=items.length, dp=Array.from({length:n+1},()=>Array(capacity+1).fill(0));
  for(let i=1;i<=n;i++) {
    const [weight,value]=items[i-1];
    for(let c=0;c<=capacity;c++) {
      dp[i][c]=dp[i-1][c];
      if(weight<=c)dp[i][c]=Math.max(dp[i][c],value+dp[i-1][c-weight]);
    }
  }
  const chosen=[];let c=capacity;
  for(let i=n;i>0;i--)if(dp[i][c]!==dp[i-1][c]){chosen.push(i-1);c-=items[i-1][0];}
  return {value:dp[n][capacity],chosen:chosen.reverse()};
}
function knapsackValue(items, capacity) {
  const dp=Array(capacity+1).fill(0);
  for(const [weight,value] of items)
    for(let c=capacity;c>=weight;c--)dp[c]=Math.max(dp[c],value+dp[c-weight]);
  return dp[capacity];
}
