import java.util.*;
class Main {
  static long[][] table(int[][] items,int capacity){
    if(capacity<0)throw new IllegalArgumentException("capacity");
    for(int[] item:items)if(item[0]<=0||item[1]<0)throw new IllegalArgumentException("item");
    long[][] dp=new long[items.length+1][capacity+1];
    for(int i=1;i<=items.length;i++)for(int c=0;c<=capacity;c++){
      int w=items[i-1][0],v=items[i-1][1];dp[i][c]=dp[i-1][c];
      if(w<=c)dp[i][c]=Math.max(dp[i][c],v+dp[i-1][c-w]);
    }
    return dp;
  }
  static List<Integer> reconstruct(int[][] items,int capacity,long[][] dp){
    List<Integer> chosen=new ArrayList<>();int c=capacity;
    for(int i=items.length;i>0;i--)if(dp[i][c]!=dp[i-1][c]){chosen.add(i-1);c-=items[i-1][0];}
    Collections.reverse(chosen);return chosen;
  }
  public static void main(String[] args){int[][] items={{2,3},{3,4},{4,5},{5,8}};long[][] dp=table(items,7);System.out.println(dp[items.length][7]);System.out.println(reconstruct(items,7,dp));}
}
